const body = $json.body;
console.log('Incoming form data:', JSON.stringify(body, null, 2));
if (!body || typeof body !== 'object') throw new Error('400: Missing body');

const safeArray = v => Array.isArray(v) ? v : (v ? [v] : []);

const normaliseAgeRange = arr => arr.map(v => {
  if (v === 'Kids')      return 'Kids_0_12';
  if (v === 'Teens')     return 'Teens_13_19';
  if (v === 'Adults')    return 'Adults_20_39';
  if (v === 'MiddleAge') return 'Adults_40_59';
  if (v === 'Seniors')   return 'Seniors_60plus';
  return v;
});

const flexDates = body.flexDates === 'yes' || body.flexDates === true || body.flexDates === 'true';

return [{ json: {
  // Step 1: Who & Vibe
  tripType:           body.tripType           || 'Not specified',
  groupSize:          body.groupSize          || '1',
  travelPace:         body.travelPace         || 'Balanced',
  budgetTier:         body.budgetTier         || 'Standard',
  ageRange:           normaliseAgeRange(safeArray(body.ageRange)),
  anniversaryUpgrade: body.anniversaryUpgrade === 'yes' || body.anniversaryUpgrade === true,
  specialOccasion:    body.specialOccasion    || 'None',
  // Step 2: Travel Details
  departurePort:      body.departurePort      || 'Not specified',
  cruiseRegion:       body.cruiseRegion       || 'Not specified',
  startDate:          body.startDate          || '',
  endDate:            body.endDate            || '',
  flexDates,
  cruiseDuration:     body.cruiseDuration     || 'Not specified',
  // Step 3: Onboard
  onboardPreferences: safeArray(body.onboardPreferences),
  cabinType:          body.cabinType          || 'Not specified',
  dietaryNeeds:       body.dietaryNeeds       || 'None',
  // Step 4: Shore Excursions
  shoreExcursions:    safeArray(body.shoreExcursions),
  // Step 5: Budget & Contact
  budget:             body.budget             || '0',
  email:              (body.email || '').trim()
}}];

const {
  tripType, groupSize, travelPace, budgetTier, ageRange,
  anniversaryUpgrade, specialOccasion,
  departurePort, cruiseRegion, startDate, endDate, flexDates, cruiseDuration,
  onboardPreferences, cabinType, dietaryNeeds, shoreExcursions,
  budget, email
} = $json;

const fmt = v => Array.isArray(v) && v.length ? v.join(', ') : 'No preference';

const paceLabel = {
  Relaxed:  'Relaxed & slow (max 2 shore excursions per port, spa days, long sea days)',
  Balanced: 'Balanced (2–3 activities per port, mix of exploration and rest)',
  Active:   'Packed & active (every port day fully booked, morning to evening)',
}[travelPace] || travelPace;

const tierLabel = {
  Economy:  'Economy — interior cabins, budget cruise lines, self-guided port days',
  Standard: 'Standard — oceanview/balcony cabin, guided shore excursions, specialty dining',
  Elite:    'Elite — suite class, luxury cruise lines, private excursions, fine dining',
}[budgetTier] || budgetTier;

const dateLine = flexDates
  ? 'Flexible — suggest the optimal sailing season for this region'
  : (startDate && endDate ? `${startDate} to ${endDate}` : 'Not specified');

const prompt = `Please create a complete cruise itinerary with the following details:

- Departure Port: ${departurePort}
- Cruise Region: ${cruiseRegion}
- Travel Dates: ${dateLine}
- Cruise Duration: ${cruiseDuration} nights
- Trip Type: ${tripType}
- Travel Pace: ${paceLabel}
- Plan Tier: ${tierLabel}
- Total Budget: $${budget} USD
- Group Size: ${groupSize}
- Age Ranges: ${fmt(ageRange)}
- Cabin Type: ${cabinType}
- Onboard Preferences: ${fmt(onboardPreferences)}
- Shore Excursion Interests: ${fmt(shoreExcursions)}
- Dietary Needs: ${dietaryNeeds}
- Special Occasion: ${specialOccasion}
- Surprise Romance Upgrade: ${anniversaryUpgrade ? 'YES — include a special romantic gesture' : 'No'}

Please follow all formatting and content rules from the system prompt exactly.`;

return [{ json: {
  tripType, groupSize, travelPace, budgetTier, ageRange,
  anniversaryUpgrade, specialOccasion,
  departurePort, cruiseRegion, startDate, endDate, flexDates, cruiseDuration,
  onboardPreferences, cabinType, dietaryNeeds, shoreExcursions,
  budget, email, prompt
}}];

const destination      = $json.cruiseRegion       || 'Your Destination';
const departurePort    = $json.departurePort      || 'Not specified';
const flexDates        = $json.flexDates          || false;
const travelDates      = flexDates
  ? 'Flexible — Genie will suggest optimal dates'
  : `${$json.startDate || 'N/A'} to ${$json.endDate || 'N/A'}`;
const cruiseDuration   = $json.cruiseDuration     || 'Not specified';
const budget           = $json.budget             || 'N/A';
const groupSize        = $json.groupSize          || 'N/A';
const tripType         = $json.tripType           || 'N/A';
const travelPace       = $json.travelPace         || '';
const budgetTier       = $json.budgetTier         || 'Standard';
const cabinType        = $json.cabinType          || 'Not specified';
const anniversaryUpgrade = $json.anniversaryUpgrade || false;
const specialOccasion  = $json.specialOccasion    || 'None';
const dietaryNeeds     = $json.dietaryNeeds       || 'None';
const onboardPrefs     = Array.isArray($json.onboardPreferences) ? $json.onboardPreferences.join(', ') : $json.onboardPreferences || 'Not specified';
const shoreExc         = Array.isArray($json.shoreExcursions)    ? $json.shoreExcursions.join(', ')    : $json.shoreExcursions    || 'Not specified';
const ageRange         = Array.isArray($json.ageRange)           ? $json.ageRange.join(', ')           : $json.ageRange           || 'Not specified';
const itineraryContent = $json.itinerary          || 'Itinerary details not available.';

const tierBadge  = { Economy: '🟢 Economy', Standard: '🔵 Standard', Elite: '⭐ Elite' }[budgetTier] || budgetTier;
const paceLabel  = { Relaxed: '🌅 Relaxed', Balanced: '🌊 Balanced', Active: '🏄 Active' }[travelPace] || travelPace;

const metaRow = (label, value) =>
  `<p style="color:#333;font-size:15px;margin:8px 0;line-height:1.5;"><strong style="color:#023e8a;">${label}:</strong> ${value}</p>`;

const emailHtml = `
<div style="font-family:'Helvetica Neue',Arial,sans-serif;max-width:660px;margin:0 auto;background:#f8fafc;padding:24px;border-radius:12px;">
  <div style="background:linear-gradient(105deg,#023e8a,#0077b6);padding:26px 28px;border-radius:10px 10px 0 0;text-align:center;">
    <h1 style="color:#fff;margin:0;font-size:26px;font-family:Georgia,serif;">🚢 Your Cruise Itinerary</h1>
    <p style="color:rgba(255,255,255,0.8);margin:6px 0 0;font-size:14px;">Generated by Voyage Genie · ${tierBadge}</p>
  </div>
  <div style="background:#fff;padding:28px;border-radius:0 0 10px 10px;border:1px solid #e2e8f0;border-top:none;">
    <h2 style="color:#023e8a;font-size:18px;margin:0 0 16px;border-bottom:2px solid #eaf4fb;padding-bottom:10px;">Trip Overview</h2>
    ${metaRow('⚓ Departing from', departurePort)}
    ${metaRow('🌍 Cruise Region', destination)}
    ${metaRow('📅 Travel Dates', travelDates)}
    ${metaRow('⏳ Duration', cruiseDuration + ' nights')}
    ${metaRow('🛏️ Cabin Type', cabinType)}
    ${metaRow('🧳 Trip Type', tripType)}
    ${paceLabel ? metaRow('⚡ Travel Pace', paceLabel) : ''}
    ${metaRow('⭐ Plan Tier', tierBadge)}
    ${metaRow('👥 Group Size', groupSize + ' traveler(s)')}
    ${ageRange ? metaRow('👨‍👩‍👧 Age Ranges', ageRange) : ''}
    ${metaRow('🎉 Onboard Preferences', onboardPrefs)}
    ${metaRow('🏝️ Shore Excursion Interests', shoreExc)}
    ${dietaryNeeds !== 'None' ? metaRow('🍽️ Dietary Needs', dietaryNeeds) : ''}
    ${specialOccasion !== 'None' ? metaRow('🎂 Special Occasion', specialOccasion) : ''}
    ${anniversaryUpgrade ? metaRow('💍 Romantic Upgrade', 'Requested') : ''}
    ${metaRow('💵 Budget', '$' + budget)}
    <hr style="border:0;border-top:1px solid #e2e8f0;margin:20px 0;">
    <h3 style="color:#023e8a;font-size:16px;margin:0 0 14px;">Your Itinerary Details</h3>
    <div style="background:#f8fafc;padding:20px;border-radius:8px;font-size:14px;line-height:1.7;color:#1e293b;border:1px solid #e2e8f0;">
      ${itineraryContent}
    </div>
    <hr style="border:0;border-top:1px solid #e2e8f0;margin:24px 0 16px;">
    <p style="color:#64748b;font-size:12px;text-align:center;margin:0;">
      Generated by <strong>Voyage Genie</strong> 🌟 &nbsp;|&nbsp; Plan Less, Explore More
    </p>
  </div>
</div>`;

const sessionId = Date.now().toString();
const subject   = `Your ${tierBadge} Cruise Itinerary for ${destination} – Voyage Genie`;

const formData = {
  departurePort, cruiseRegion: destination,
  startDate: $json.startDate || '', endDate: $json.endDate || '',
  flexDates, cruiseDuration, tripType, travelPace, budgetTier,
  cabinType, groupSize, budget,
  onboardPreferences: $json.onboardPreferences || [],
  shoreExcursions:    $json.shoreExcursions    || [],
  ageRange:           $json.ageRange           || [],
  dietaryNeeds, specialOccasion, anniversaryUpgrade
};

console.log('Resolved email for:', $json.email, '| sessionId:', sessionId);

return [{ json: {
  sessionId,
  itineraryHtml:   itineraryContent,  // clean AI content for frontend display
  emailHtml:       emailHtml,         // full branded wrapper for email sending
  resolvedEmail:   ($json.email || '').trim(),
  resolvedSubject: subject,
  resolvedMessage: emailHtml,
  formData
}}];

return [{ json: {
  sessionId:     $json.sessionId,
  redirectUrl:   $json.redirectUrl,
  itineraryData: $json.itineraryData,
  itineraryHtml: $json.itineraryHtml,
  emailHtml:     $json.emailHtml
}}];

console.log('Request Details:', JSON.stringify($json, null, 2));
let method = $json.method;
if (!method) {
  method = $json.headers[':method'] || 'POST';
}
return [{ json: { ...$json, method: method } }];

// ── Extract raw AI output ──
const itineraryRaw = $node['OpenAI'].json.message?.content || 'No itinerary found.';
console.log('Raw OpenAI output (first 300 chars):', itineraryRaw.substring(0, 300));

const HEADING_COLOR = '#023e8a';
const HEADING_STYLE = `font-size:16px;color:${HEADING_COLOR};display:block;margin:18px 0 6px 0;font-weight:600;`;
const TABLE_CELL    = 'border:1px solid #e2e8f0;padding:9px 12px;font-size:14px;';
const TABLE_BOLD    = 'border:1px solid #e2e8f0;padding:9px 12px;font-size:14px;background:#eaf4fb;font-weight:600;color:#023e8a;';

// Pre-process: normalise literal \t (AI sometimes outputs backslash-t instead of real tab)
// then strip markdown and convert **bold**
let processed = itineraryRaw
  .replace(/\\t/g, '\t')
  .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
  // Convert ### headings to section format
  .replace(/^#{1,3}\s+(.+)$/gm, '$1:')
  // Normalise line endings
  .replace(/\r\n/g, '\n');

const lines = processed.split('\n');
let html = '';
let inCostSummary = false;
let inDailySchedule = false;
let costRows = [];
let scheduleLines = [];

function flushCostTable() {
  if (costRows.length === 0) return '';
  const rows = costRows.join('');
  costRows = [];
  return `<table style="border-collapse:collapse;width:100%;margin:12px 0;" cellpadding="0" cellspacing="0">${rows}</table><br>`;
}

function flushDailySchedule(schedLines) {
  let out = `<strong style="${HEADING_STYLE}">Daily Schedule:</strong>`;
  const joined = schedLines.join('\n');
  const dayBlocks = joined.split(/(?=<strong>Day \d+:)/);
  for (const block of dayBlocks) {
    if (!block.trim()) continue;
    const bulletLines = block.split('\n').map(l => {
      const t = l.trim();
      if (!t) return '';
      if (t.startsWith('<strong>')) return t + '<br>';
      if (t.startsWith('- ')) return `<span style="display:block;padding-left:1em;margin:2px 0;">${t.slice(2)}</span>`;
      return t + '<br>';
    });
    out += bulletLines.join('');
  }
  return out + '<br>';
}

for (let i = 0; i < lines.length; i++) {
  const raw = lines[i];
  const line = raw.trim();

  if (!line) {
    if (inCostSummary) {
      html += flushCostTable();
      inCostSummary = false;
    } else if (inDailySchedule) {
      html += flushDailySchedule(scheduleLines);
      inDailySchedule = false;
      scheduleLines = [];
    } else {
      html += '<br>';
    }
    continue;
  }

  const lower = line.toLowerCase();

  // Daily Schedule section
  if (lower.startsWith('daily schedule:')) {
    if (inCostSummary) { html += flushCostTable(); inCostSummary = false; }
    inDailySchedule = true;
    scheduleLines = [];
    continue;
  }
  if (inDailySchedule) {
    scheduleLines.push(line);
    continue;
  }

  // Cost Summary section
  if (lower.startsWith('cost summary:')) {
    html += `<strong style="${HEADING_STYLE}">Cost Summary:</strong>`;
    inCostSummary = true;
    costRows = [];
    continue;
  }
  if (inCostSummary) {
    if (line.includes('\t')) {
      const parts = line.split('\t').map(s => s.replace(/<[^>]+>/g,'').trim());
      const cat  = parts[0] || '';
      const cost = parts[1] || '';
      const isTotals = cat.match(/^(Total|Remaining Budget)/i);
      const style = isTotals ? TABLE_BOLD : TABLE_CELL;
      costRows.push(`<tr><td style="${style}">${cat}</td><td style="${style};text-align:right;">${cost}</td></tr>`);
      continue;
    } else if (line.match(/^[-•]/)) {
      // bullet inside cost section — close table first
      html += flushCostTable();
      inCostSummary = false;
      // fall through
    } else {
      html += flushCostTable();
      inCostSummary = false;
      // fall through
    }
  }

  // Section headings — end with colon, no inner HTML tags, not a bullet
  if (line.endsWith(':') && !line.startsWith('-') && !line.startsWith('•') && !line.includes('<a ')) {
    html += `<strong style="${HEADING_STYLE}">${line}</strong>`;
    continue;
  }

  // Bullet points
  if (line.startsWith('- ') || line.startsWith('• ')) {
    const text = line.startsWith('- ') ? line.slice(2) : line.slice(2);
    html += `<span style="display:block;padding-left:1em;margin:2px 0;">• ${text}</span>`;
    continue;
  }

  // Everything else
  html += line + '<br>';
}

// Flush anything still open at end of input
if (inCostSummary) html += flushCostTable();
if (inDailySchedule) html += flushDailySchedule(scheduleLines);

// Fallback Cost Summary if none found
const budget = $json.budget || '0';
if (!html.toLowerCase().includes('cost summary:')) {
  html += `<strong style="${HEADING_STYLE}">Cost Summary:</strong>`;
  html += `<table style="border-collapse:collapse;width:100%;margin:12px 0;" cellpadding="0" cellspacing="0">
    <tr><td style="${TABLE_CELL}">Cruise Fare</td><td style="${TABLE_CELL};text-align:right;">$0</td></tr>
    <tr><td style="${TABLE_CELL}">Onboard Activities</td><td style="${TABLE_CELL};text-align:right;">$0</td></tr>
    <tr><td style="${TABLE_CELL}">Shore Excursions</td><td style="${TABLE_CELL};text-align:right;">$0</td></tr>
    <tr><td style="${TABLE_CELL}">Food</td><td style="${TABLE_CELL};text-align:right;">$0</td></tr>
    <tr><td style="${TABLE_BOLD}">Total</td><td style="${TABLE_BOLD};text-align:right;">$0</td></tr>
    <tr><td style="${TABLE_BOLD}">Remaining Budget</td><td style="${TABLE_BOLD};text-align:right;">$${budget}</td></tr>
  </table><br>`;
}

console.log('Formatted itinerary HTML (first 500 chars):', html.substring(0, 500));
return [{ json: { ...$json, itinerary: html } }];
